@import "tailwindcss";

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: #f9fafb;
  color: #111827;
}

import React, { createContext, useContext, useState, useEffect, useMemo } from 'react';

export interface Expense {
  id: string;
  description: string;
  amount: number;
  category: string;
  date: string;
}

interface CategoryBreakdownItem {
  amount: number;
  percentage: number;
}

interface ExpenseContextType {
  expenses: Expense[];
  filteredExpenses: Expense[];
  selectedCategory: string;
  setSelectedCategory: (category: string) => void;
  addExpense: (expense: Omit<Expense, 'id'>) => void;
  deleteExpense: (id: string) => void;
  totalBalance: number;
  categoryBreakdown: Record<string, CategoryBreakdownItem>;
  categories: string[];
}

export const ExpenseContext = createContext<ExpenseContextType | undefined>(undefined);

const LOCAL_STORAGE_KEY = 'expense_tracker_expenses_data';
const DEFAULT_CATEGORIES = ['Food', 'Housing', 'Utilities', 'Entertainment', 'Transportation', 'Other'];

export const ExpenseProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [expenses, setExpenses] = useState<Expense[]>(() => {
    try {
      const stored = localStorage.getItem(LOCAL_STORAGE_KEY);
      return stored ? JSON.parse(stored) : [];
    } catch (error) {
      console.error('Failed to parse expenses from localStorage', error);
      return [];
    }
  });

  const [selectedCategory, setSelectedCategory] = useState<string>('All');

  useEffect(() => {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(expenses));
  }, [expenses]);

  const addExpense = (newExpense: Omit<Expense, 'id'>) => {
    if (
      !newExpense.description.trim() ||
      newExpense.amount <= 0 ||
      !newExpense.category ||
      !newExpense.date
    ) {
      return;
    }

    const expense: Expense = {
      ...newExpense,
      id: crypto.randomUUID(),
      description: newExpense.description.trim(),
    };

    setExpenses((prev) => [expense, ...prev]);
  };

  const deleteExpense = (id: string) => {
    setExpenses((prev) => prev.filter((item) => item.id !== id));
  };

  const totalBalance = useMemo(() => {
    return expenses.reduce((sum, item) => sum + item.amount, 0);
  }, [expenses]);

  const categoryBreakdown = useMemo(() => {
    const breakdown: Record<string, CategoryBreakdownItem> = {};

    expenses.forEach((item) => {
      if (!breakdown[item.category]) {
        breakdown[item.category] = { amount: 0, percentage: 0 };
      }
      breakdown[item.category].amount += item.amount;
    });

    if (totalBalance > 0) {
      Object.keys(breakdown).forEach((cat) => {
        breakdown[cat].percentage = Math.round((breakdown[cat].amount / totalBalance) * 100);
      });
    }

    return breakdown;
  }, [expenses, totalBalance]);

  const filteredExpenses = useMemo(() => {
    if (selectedCategory === 'All') {
      return expenses;
    }
    return expenses.filter((item) => item.category === selectedCategory);
  }, [expenses, selectedCategory]);

  const categories = useMemo(() => {
    const uniqueFromExpenses = Array.from(new Set(expenses.map((e) => e.category)));
    const merged = Array.from(new Set([...DEFAULT_CATEGORIES, ...uniqueFromExpenses]));
    return merged.filter(Boolean);
  }, [expenses]);

  return (
    <ExpenseContext.Provider
      value={{
        expenses,
        filteredExpenses,
        selectedCategory,
        setSelectedCategory,
        addExpense,
        deleteExpense,
        totalBalance,
        categoryBreakdown,
        categories,
      }}
    >
      {children}
    </ExpenseContext.Provider>
  );
};

export const useExpenses = () => {
  const context = useContext(ExpenseContext);
  if (context === undefined) {
    throw new Error('useExpenses must be used within an ExpenseProvider');
  }
  return context;
};

import React, { useContext } from 'react';
import { ExpenseContext } from '../context/ExpenseContext';

export const CategoryFilter: React.FC = () => {
  const context = useContext(ExpenseContext);

  if (!context) return null;

  const { categories, selectedCategory, setSelectedCategory } = context;

  return (
    <div className="w-full max-w-xs">
      <label 
        htmlFor="category-filter" 
        className="sr-only"
      >
        Filter by Category
      </label>
      <select
        id="category-filter"
        value={selectedCategory}
        onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setSelectedCategory(e.target.value)}
        className="w-full p-2 bg-white border border-gray-300 rounded-lg shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 text-sm"
      >
        <option value="All">All Categories</option>
        {categories.map((category) => (
          <option key={category} value={category}>
            {category}
          </option>
        ))}
      </select>
    </div>
  );
};

import React, { useContext } from 'react';
import { Trash2, Calendar, Tag, Inbox } from 'lucide-react';
import { ExpenseContext } from '../context/ExpenseContext';

interface Expense {
  id: string;
  description: string;
  amount: number;
  category: string;
  date: string;
}

export const ExpenseList: React.FC = () => {
  const context = useContext(ExpenseContext);

  if (!context) {
    return (
      <div className="p-4 text-center text-red-500 bg-red-50 rounded-lg border border-red-200">
        Expense context not found. Please ensure ExpenseProvider is wrapping the application.
      </div>
    );
  }

  // Fallback to expenses if filteredExpenses is not defined
  const filteredExpenses = (context.filteredExpenses || context.expenses || []) as Expense[];
  const deleteExpense = context.deleteExpense;

  const formatDate = (dateString: string) => {
    if (!dateString) return '';
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString(undefined, {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
      });
    } catch (e) {
      return dateString;
    }
  };

  const formatAmount = (amount: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
    }).format(amount);
  };

  if (filteredExpenses.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center p-8 text-center bg-white border border-dashed border-slate-200 rounded-2xl shadow-sm">
        <div className="p-3 bg-slate-50 rounded-full text-slate-400 mb-3">
          <Inbox className="w-8 h-8" />
        </div>
        <h3 className="text-sm font-semibold text-slate-800">No expenses found</h3>
        <p className="text-xs text-slate-500 mt-1 max-w-[240px]">
          There are no expenses matching your current filters or none have been added yet.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between px-1">
        <h2 className="text-xs font-bold text-slate-400 uppercase tracking-wider">
          Transactions ({filteredExpenses.length})
        </h2>
      </div>

      <div className="space-y-3 max-h-[500px] overflow-y-auto pr-1">
        {filteredExpenses.map((expense) => (
          <div
            key={expense.id}
            className="group flex items-center justify-between p-4 bg-white hover:bg-slate-50 border border-slate-100 rounded-xl shadow-sm transition-all duration-200"
          >
            <div className="flex items-start gap-3 min-w-0 flex-1">
              <div className="p-2.5 bg-slate-50 text-slate-500 rounded-lg group-hover:bg-slate-100 transition-colors duration-200 shrink-0">
                <Tag className="w-4 h-4" />
              </div>
              <div className="min-w-0 flex-1">
                <h4 className="text-sm font-medium text-slate-800 truncate" title={expense.description}>
                  {expense.description}
                </h4>
                <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mt-1 text-xs text-slate-500">
                  <span className="inline-flex items-center font-medium text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-full text-[10px]">
                    {expense.category}
                  </span>
                  <span className="inline-flex items-center gap-1">
                    <Calendar className="w-3 h-3 text-slate-400" />
                    {formatDate(expense.date)}
                  </span>
                </div>
              </div>
            </div>

            <div className="flex items-center gap-4 ml-4 shrink-0">
              <span className="text-sm font-semibold text-slate-900">
                {formatAmount(expense.amount)}
              </span>
              <button
                onClick={() => deleteExpense && deleteExpense(expense.id)}
                className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all duration-200"
                aria-label="Delete expense"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState, useContext } from 'react';
import { PlusCircle, DollarSign, Calendar, Tag, FileText } from 'lucide-react';
import { ExpenseContext } from '../context/ExpenseContext';

export const ExpenseForm: React.FC = () => {
  const context = useContext(ExpenseContext);

  if (!context) {
    throw new Error('ExpenseForm must be used within an ExpenseProvider');
  }

  const { addExpense } = context;

  const [description, setDescription] = useState('');
  const [amount, setAmount] = useState('');
  const [category, setCategory] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [error, setError] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    const trimmedDescription = description.trim();
    const parsedAmount = parseFloat(amount);

    if (!trimmedDescription) {
      setError('Description is required.');
      return;
    }

    if (isNaN(parsedAmount) || parsedAmount <= 0) {
      setError('Amount must be a positive number greater than 0.');
      return;
    }

    if (!category) {
      setError('Please select a category.');
      return;
    }

    if (!date) {
      setError('Please select a date.');
      return;
    }

    addExpense({
      description: trimmedDescription,
      amount: parsedAmount,
      category,
      date,
    });

    // Reset fields to default
    setDescription('');
    setAmount('');
    setCategory('');
    setDate(new Date().toISOString().split('T')[0]);
  };

  const categories = [
    'Food',
    'Entertainment',
    'Utilities',
    'Transportation',
    'Housing',
    'Other'
  ];

  return (
    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm p-6 max-w-md w-full mx-auto">
      <h2 className="text-xl font-semibold text-gray-800 mb-6 flex items-center gap-2">
        <PlusCircle className="w-5 h-5 text-indigo-600" />
        Add New Expense
      </h2>

      <form onSubmit={handleSubmit} className="space-y-4">
        {error && (
          <div className="p-3 text-sm text-red-600 bg-red-50 rounded-lg border border-red-100">
            {error}
          </div>
        )}

        {/* Description Input */}
        <div>
          <label htmlFor="description" className="block text-sm font-medium text-gray-700 mb-1">
            Description
          </label>
          <div className="relative">
            <span className="absolute inset-y-0 left-0 pl-3 flex items-center text-gray-400">
              <FileText className="w-4 h-4" />
            </span>
            <input
              type="text"
              id="description"
              placeholder="e.g., Grocery Shopping"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="pl-9 pr-3 py-2 w-full border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm"
              required
            />
          </div>
        </div>

        {/* Amount Input */}
        <div>
          <label htmlFor="amount" className="block text-sm font-medium text-gray-700 mb-1">
            Amount ($)
          </label>
          <div className="relative">
            <span className="absolute inset-y-0 left-0 pl-3 flex items-center text-gray-400">
              <DollarSign className="w-4 h-4" />
            </span>
            <input
              type="number"
              id="amount"
              step="0.01"
              min="0.01"
              placeholder="0.00"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              className="pl-9 pr-3 py-2 w-full border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm"
              required
            />
          </div>
        </div>

        {/* Category Select */}
        <div>
          <label htmlFor="category" className="block text-sm font-medium text-gray-700 mb-1">
            Category
          </label>
          <div className="relative">
            <span className="absolute inset-y-0 left-0 pl-3 flex items-center text-gray-400 pointer-events-none">
              <Tag className="w-4 h-4" />
            </span>
            <select
              id="category"
              value={category}
              onChange={(e) => setCategory(e.target.value)}
              className="pl-9 pr-3 py-2 w-full border border-gray-200 rounded-lg bg-white focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm appearance-none"
              required
            >
              <option value="" disabled>Select a category</option>
              {categories.map((cat) => (
                <option key={cat} value={cat}>
                  {cat}
                </option>
              ))}
            </select>
          </div>
        </div>

        {/* Date Input */}
        <div>
          <label htmlFor="date" className="block text-sm font-medium text-gray-700 mb-1">
            Date
          </label>
          <div className="relative">
            <span className="absolute inset-y-0 left-0 pl-3 flex items-center text-gray-400">
              <Calendar className="w-4 h-4" />
            </span>
            <input
              type="date"
              id="date"
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="pl-9 pr-3 py-2 w-full border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm"
              required
            />
          </div>
        </div>

        <button
          type="submit"
          className="w-full mt-2 bg-indigo-600 hover:bg-indigo-700 text-white font-medium py-2.5 px-4 rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:ring-offset-2 text-sm flex items-center justify-center gap-2"
        >
          <PlusCircle className="w-4 h-4" />
          Add Expense
        </button>
      </form>
    </div>
  );
};

import React, { useContext } from 'react';
import { DollarSign, PieChart, TrendingDown } from 'lucide-react';
import { ExpenseContext } from '../context/ExpenseContext';

interface Expense {
  id: string;
  description: string;
  amount: number;
  category: string;
  date: string;
}

export function ExpenseSummary() {
  const context = useContext(ExpenseContext);

  if (!context) {
    return (
      <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100">
        <p className="text-slate-500 text-sm">No expense context found.</p>
      </div>
    );
  }

  const { expenses } = context as { expenses: Expense[] };

  // Calculate total spending
  const totalSpending = expenses.reduce((sum, item) => sum + Number(item.amount || 0), 0);

  // Calculate category spending
  const categoryMap: { [key: string]: number } = {};
  expenses.forEach((expense) => {
    const cat = expense.category || 'Others';
    categoryMap[cat] = (categoryMap[cat] || 0) + Number(expense.amount || 0);
  });

  const categories = Object.entries(categoryMap)
    .map(([name, amount]) => {
      const percentage = totalSpending > 0 ? (amount / totalSpending) * 100 : 0;
      return { name, amount, percentage };
    })
    .sort((a, b) => b.amount - a.amount);

  // Category color mapping helper
  const getCategoryColorClass = (category: string) => {
    const cat = category.toLowerCase();
    if (cat.includes('food') || cat.includes('dining') || cat.includes('grocer')) return 'bg-emerald-500';
    if (cat.includes('housing') || cat.includes('rent') || cat.includes('home')) return 'bg-blue-500';
    if (cat.includes('utilit') || cat.includes('bill') || cat.includes('power')) return 'bg-amber-500';
    if (cat.includes('entertain') || cat.includes('leisure') || cat.includes('movie') || cat.includes('game')) return 'bg-purple-500';
    if (cat.includes('transport') || cat.includes('travel') || cat.includes('gas') || cat.includes('car')) return 'bg-indigo-500';
    return 'bg-slate-500';
  };

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
      {/* Total Balance Card */}
      <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 flex flex-col justify-between md:col-span-1">
        <div>
          <div className="flex items-center justify-between mb-4">
            <span className="text-sm font-medium text-slate-500">Total Expenses</span>
            <div className="p-2 bg-rose-50 text-rose-500 rounded-lg">
              <TrendingDown className="w-5 h-5" />
            </div>
          </div>
          <h3 className="text-3xl font-bold text-slate-900">
            ${totalSpending.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </h3>
        </div>
        <p className="text-xs text-slate-400 mt-4">
          Accumulated across {expenses.length} transaction{expenses.length !== 1 ? 's' : ''}
        </p>
      </div>

      {/* Visual Breakdown Card */}
      <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-100 md:col-span-2">
        <div className="flex items-center gap-2 mb-4">
          <PieChart className="w-5 h-5 text-slate-500" />
          <h3 className="text-base font-semibold text-slate-800">Category Breakdown</h3>
        </div>

        {categories.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-28 text-slate-400">
            <p className="text-sm">No expense data available</p>
            <p className="text-xs">Add expenses to see the visual breakdown.</p>
          </div>
        ) : (
          <div className="space-y-4 max-h-[180px] overflow-y-auto pr-1">
            {categories.map(({ name, amount, percentage }) => (
              <div key={name} className="space-y-1">
                <div className="flex justify-between text-sm font-medium">
                  <span className="text-slate-700 capitalize">{name}</span>
                  <span className="text-slate-900 font-semibold">
                    ${amount.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}{' '}
                    <span className="text-xs text-slate-400 font-normal">({percentage.toFixed(0)}%)</span>
                  </span>
                </div>
                <div className="w-full bg-slate-100 rounded-full h-2">
                  <div
                    className={`h-2 rounded-full transition-all duration-500 ${getCategoryColorClass(name)}`}
                    style={{ width: `${percentage}%` }}
                  ></div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import React from 'react';
import { ExpenseProvider } from './context/ExpenseContext';
import { ExpenseForm } from './components/ExpenseForm';
import { ExpenseList } from './components/ExpenseList';
import { ExpenseSummary } from './components/ExpenseSummary';
import { CategoryFilter } from './components/CategoryFilter';

export const App: React.FC = () => {
  return (
    <ExpenseProvider>
      <div className="min-h-screen bg-gray-50 p-4 md:p-8">
        <div className="max-w-4xl mx-auto space-y-6">
          <header className="mb-8">
            <h1 className="text-3xl font-bold text-gray-900">Expense Tracker</h1>
          </header>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="md:col-span-2 space-y-6">
              <ExpenseSummary />
              <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200">
                <div className="flex items-center justify-between mb-4">
                  <h2 className="text-lg font-semibold">Recent Expenses</h2>
                  <CategoryFilter />
                </div>
                <ExpenseList />
              </div>
            </div>

            <aside>
              <div className="sticky top-8">
                <ExpenseForm />
              </div>
            </aside>
          </div>
        </div>
      </div>
    </ExpenseProvider>
  );
};

