@import "tailwindcss";

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: #f9fafb;
  color: #111827;
}

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';

export interface Task {
  id: string;
  title: string;
  description: string;
  priority: 'Low' | 'Medium' | 'High';
  status: 'To Do' | 'In Progress' | 'Done';
}

interface BoardContextType {
  tasks: Task[];
  searchQuery: string;
  setSearchQuery: (query: string) => void;
  priorityFilter: string;
  setPriorityFilter: (filter: string) => void;
  isModalOpen: boolean;
  setIsModalOpen: (isOpen: boolean) => void;
  activeTask: Task | null;
  setActiveTask: (task: Task | null) => void;
  addTask: (title: string, description: string, priority: 'Low' | 'Medium' | 'High', status: 'To Do' | 'In Progress' | 'Done') => void;
  updateTask: (id: string, updatedFields: Partial<Omit<Task, 'id'>>) => void;
  deleteTask: (id: string) => void;
  moveTask: (id: string, newStatus: Task['status']) => void;
}

const BoardContext = createContext<BoardContextType | undefined>(undefined);

const defaultTasks: Task[] = [
  {
    id: '1',
    title: 'Create a new task',
    description: 'Click the "+ Add Task" button to start managing your workflow.',
    priority: 'Low',
    status: 'To Do',
  },
  {
    id: '2',
    title: 'Drag and drop tasks',
    description: 'Try dragging tasks between columns to update their status instantly.',
    priority: 'Medium',
    status: 'In Progress',
  },
  {
    id: '3',
    title: 'Filter tasks',
    description: 'Use the search bar and priority filter to find specific tasks in your board.',
    priority: 'High',
    status: 'Done',
  },
];

export const BoardProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [tasks, setTasks] = useState<Task[]>(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('kanban_tasks');
      if (saved) {
        try {
          const parsed = JSON.parse(saved);
          return Array.isArray(parsed) ? parsed.map(t => ({ ...t, id: String(t.id) })) : defaultTasks;
        } catch (e) {
          console.error('Failed to parse saved tasks from localStorage', e);
        }
      }
    }
    return defaultTasks;
  });

  const [searchQuery, setSearchQuery] = useState('');
  const [priorityFilter, setPriorityFilter] = useState('All');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeTask, setActiveTask] = useState<Task | null>(null);

  useEffect(() => {
    localStorage.setItem('kanban_tasks', JSON.stringify(tasks));
  }, [tasks]);

  const addTask = useCallback((title: string, description: string, priority: 'Low' | 'Medium' | 'High', status: 'To Do' | 'In Progress' | 'Done') => {
    if (!title.trim()) return;
    const newTask: Task = {
      id: crypto.randomUUID(),
      title: title.trim(),
      description: description.trim(),
      priority,
      status,
    };
    setTasks((prev) => [...prev, newTask]);
  }, []);

  const updateTask = useCallback((id: string, updatedFields: Partial<Omit<Task, 'id'>>) => {
    setTasks((prev) =>
      prev.map((task) => (task.id === id ? { ...task, ...updatedFields } : task))
    );
  }, []);

  const deleteTask = useCallback((id: string) => {
    setTasks((prev) => prev.filter((task) => task.id !== id));
  }, []);

  const moveTask = useCallback((id: string, newStatus: Task['status']) => {
    setTasks((prev) =>
      prev.map((task) =>
        task.id === id ? { ...task, status: newStatus } : task
      )
    );
  }, []);

  return (
    <BoardContext.Provider
      value={{
        tasks,
        searchQuery,
        setSearchQuery,
        priorityFilter,
        setPriorityFilter,
        isModalOpen,
        setIsModalOpen,
        activeTask,
        setActiveTask,
        addTask,
        updateTask,
        deleteTask,
        moveTask,
      }}
    >
      {children}
    </BoardContext.Provider>
  );
};

export const useBoard = () => {
  const context = useContext(BoardContext);
  if (!context) {
    throw new Error('useBoard must be used within a BoardProvider');
  }
  return context;
};

import React, { useState } from 'react';
import { useBoard } from '../context/BoardContext';
import { Edit2, Trash2 } from 'lucide-react';
import clsx from 'clsx';

interface TaskCardProps {
  taskId: string;
}

export const TaskCard: React.FC<TaskCardProps> = ({ taskId }) => {
  const { tasks, setActiveTask, setIsModalOpen, deleteTask } = useBoard();
  const [isDragging, setIsDragging] = useState(false);

  const task = tasks.find((t) => t.id === taskId);

  if (!task) {
    return null;
  }

  const openModal = (task: any) => {
    setActiveTask(task);
    setIsModalOpen(true);
  };

  const handleDragStart = (e: React.DragEvent) => {
    setIsDragging(true);
    e.dataTransfer.setData('text/plain', taskId);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragEnd = () => {
    setIsDragging(false);
  };

  const getPriorityColor = (priority: string) => {
    switch (priority?.toLowerCase()) {
      case 'high':
        return 'bg-red-50 text-red-700 border-red-200';
      case 'medium':
        return 'bg-amber-50 text-amber-700 border-amber-200';
      case 'low':
      default:
        return 'bg-green-50 text-green-700 border-green-200';
    }
  };

  return (
    <div
      draggable
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      className={clsx(
        'p-4 mb-3 bg-white rounded-lg border border-slate-200 shadow-sm cursor-grab active:cursor-grabbing transition-all hover:shadow-md hover:border-slate-300',
        isDragging && 'opacity-40 border-dashed border-indigo-400 bg-indigo-50/10'
      )}
    >
      <div className="flex items-start justify-between gap-2 mb-2">
        <h4 className="font-semibold text-slate-800 text-sm leading-tight break-words flex-1">
          {task.title}
        </h4>
        <div className="flex items-center gap-1 shrink-0">
          <button
            onClick={() => openModal(task)}
            className="p-1 text-slate-400 hover:text-indigo-600 hover:bg-slate-100 rounded transition-colors"
            title="Edit Task"
            aria-label="Edit Task"
          >
            <Edit2 className="w-3.5 h-3.5" />
          </button>
          <button
            onClick={() => deleteTask(taskId)}
            className="p-1 text-slate-400 hover:text-red-600 hover:bg-slate-100 rounded transition-colors"
            title="Delete Task"
            aria-label="Delete Task"
          >
            <Trash2 className="w-3.5 h-3.5" />
          </button>
        </div>
      </div>

      {task.description && (
        <p className="text-xs text-slate-500 mb-3 line-clamp-3 break-words">
          {task.description}
        </p>
      )}

      <div className="flex items-center justify-between mt-2 pt-2 border-t border-slate-50">
        <span
          className={clsx(
            'inline-flex items-center px-2.5 py-0.5 rounded-full text-[10px] font-semibold border uppercase tracking-wider',
            getPriorityColor(task.priority)
          )}
        >
          {task.priority}
        </span>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useBoard } from '../context/BoardContext';
import { TaskCard } from './TaskCard';

interface ColumnProps {
  title: string;
  status: 'To Do' | 'In Progress' | 'Done';
}

export const Column: React.FC<ColumnProps> = ({ title, status }) => {
  const { tasks, moveTask, searchQuery, priorityFilter, setIsModalOpen, setActiveTask } = useBoard();
  const [isDraggingOver, setIsDraggingOver] = useState(false);

  const filteredTasks = tasks.filter((task) => {
    if (task.status !== status) return false;

    const matchesSearch = searchQuery
      ? task.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        (task.description && task.description.toLowerCase().includes(searchQuery.toLowerCase()))
      : true;

    const matchesPriority = priorityFilter && priorityFilter !== 'all'
      ? task.priority === priorityFilter
      : true;

    return matchesSearch && matchesPriority;
  });

  const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDraggingOver(true);
  };

  const handleDragLeave = () => {
    setIsDraggingOver(false);
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDraggingOver(false);
    const taskId = e.dataTransfer.getData('text/plain');
    if (taskId) {
      moveTask(taskId, status);
    }
  };

  const getHeaderColorClass = () => {
    switch (status) {
      case 'To Do':
        return 'border-t-4 border-blue-500';
      case 'In Progress':
        return 'border-t-4 border-amber-500';
      case 'Done':
        return 'border-t-4 border-emerald-500';
      default:
        return 'border-t-4 border-slate-500';
    }
  };

  const handleAddTaskClick = () => {
    setActiveTask(null);
    setIsModalOpen(true);
  };

  return (
    <div
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      onDrop={handleDrop}
      className={`flex flex-col flex-1 min-w-[280px] bg-slate-50 rounded-xl p-4 shadow-sm transition-all duration-200 ${getHeaderColorClass()} ${isDraggingOver ? 'bg-slate-100 ring-2 ring-blue-400 ring-dashed' : ''}`}
    >
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <h3 className="text-base font-bold text-slate-800">{title}</h3>
          <span className="flex items-center justify-center bg-slate-200 text-slate-700 text-xs font-semibold px-2 py-0.5 rounded-full">
            {filteredTasks.length}
          </span>
        </div>

        <button
          onClick={handleAddTaskClick}
          className="text-slate-400 hover:text-slate-600 transition-colors p-1 rounded-md hover:bg-slate-200"
          title={`Add task to ${title}`}
        >
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2.5} stroke="currentColor" className="w-4 h-4">
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
          </svg>
        </button>
      </div>

      <div className="flex-1 flex flex-col gap-3 overflow-y-auto min-h-[350px]">
        {filteredTasks.length > 0 ? (
          filteredTasks.map((task) => (
            <TaskCard key={task.id} taskId={task.id} />
          ))
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center border-2 border-dashed border-slate-200 rounded-xl p-6 text-slate-400 text-xs text-center select-none">
            <span>No tasks here</span>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useBoard } from '../context/BoardContext';
import { X } from 'lucide-react';

export const TaskModal: React.FC = () => {
  const { isModalOpen, activeTask, addTask, updateTask, setIsModalOpen } = useBoard();

  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [priority, setPriority] = useState<'Low' | 'Medium' | 'High'>('Medium');
  const [status, setStatus] = useState<'To Do' | 'In Progress' | 'Done'>('To Do');
  const [error, setError] = useState('');

  useEffect(() => {
    if (isModalOpen) {
      if (activeTask) {
        setTitle(activeTask.title);
        setDescription(activeTask.description);
        setPriority(activeTask.priority);
        setStatus(activeTask.status);
      } else {
        setTitle('');
        setDescription('');
        setPriority('Medium');
        setStatus('To Do');
      }
      setError('');
    }
  }, [isModalOpen, activeTask]);

  if (!isModalOpen) return null;

  const closeModal = () => setIsModalOpen(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) {
      setError('Title is required');
      return;
    }

    if (activeTask) {
      updateTask(activeTask.id, { title, description, priority, status });
    } else {
      addTask(title, description, priority, status);
    }

    closeModal();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 overflow-y-auto">
      <div className="fixed inset-0 bg-black bg-opacity-50 transition-opacity" onClick={closeModal} />
      <div className="relative bg-white rounded-lg shadow-xl max-w-md w-full z-10 overflow-hidden transform transition-all">
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200">
          <h3 className="text-lg font-semibold text-gray-900">{activeTask ? 'Edit Task' : 'Create New Task'}</h3>
          <button type="button" onClick={closeModal} className="text-gray-400 hover:text-gray-500 focus:outline-none">
            <X className="h-5 w-5" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          {error && <div className="p-3 bg-red-50 text-red-700 text-sm rounded-md">{error}</div>}

          <div>
            <label htmlFor="title" className="block text-sm font-medium text-gray-700 mb-1">Title <span className="text-red-500">*</span></label>
            <input type="text" id="title" value={title} onChange={(e) => setTitle(e.target.value)} className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 text-sm" />
          </div>

          <div>
            <label htmlFor="description" className="block text-sm font-medium text-gray-700 mb-1">Description</label>
            <textarea id="description" value={description} onChange={(e) => setDescription(e.target.value)} rows={3} className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-indigo-500 text-sm" />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label htmlFor="priority" className="block text-sm font-medium text-gray-700 mb-1">Priority</label>
              <select id="priority" value={priority} onChange={(e) => setPriority(e.target.value as any)} className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm text-sm bg-white">
                <option value="Low">Low</option>
                <option value="Medium">Medium</option>
                <option value="High">High</option>
              </select>
            </div>
            <div>
              <label htmlFor="status" className="block text-sm font-medium text-gray-700 mb-1">Status</label>
              <select id="status" value={status} onChange={(e) => setStatus(e.target.value as any)} className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm text-sm bg-white">
                <option value="To Do">To Do</option>
                <option value="In Progress">In Progress</option>
                <option value="Done">Done</option>
              </select>
            </div>
          </div>

          <div className="flex justify-end space-x-3 pt-4 border-t border-gray-200">
            <button type="button" onClick={closeModal} className="px-4 py-2 border border-gray-300 rounded-md text-sm font-medium text-gray-700 hover:bg-gray-50">Cancel</button>
            <button type="submit" className="px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700">{activeTask ? 'Save Changes' : 'Create Task'}</button>
          </div>
        </form>
      </div>
    </div>
  );
};

