  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();
    setStatus('Settings saved successfully!');
    setTimeout(() => setStatus(''), 3000);
  };

  return (
    <div className="p-6 max-w-2xl">
      <h1 className="text-2xl font-bold mb-6">Application Settings</h1>

      {status && (
        <div className="mb-4 p-3 bg-green-100 text-green-700 rounded border border-green-200">
          {status}
        </div>
      )}

      <form onSubmit={handleSave} className="space-y-6 bg-white p-6 rounded shadow-sm border border-gray-200">
        <div>
          <label className="block text-sm font-medium text-gray-700">Theme</label>
          <select
            name="theme"
            value={preferences.theme}
            onChange={handleChange}
            className="mt-1 block w-full border border-gray-300 rounded-md p-2"
          >
            <option value="light">Light</option>
            <option value="dark">Dark</option>
          </select>
        </div>

        <div>
          <label className="flex items-center space-x-2">
            <input
              type="checkbox"
