import React, { useState, useEffect, useCallback } from 'react';
import { Display } from './components/Display';
import { Keypad } from './components/Keypad';

export default function App() {
  const [expression, setExpression] = useState('0');

  const handleInput = useCallback((char: string) => {
    setExpression((prev) => {
      if (char === 'C' || char === 'Escape') return '0';
      if (char === '=' || char === 'Enter') {
        try {
          const sanitized = prev.replace(/×/g, '*').replace(/÷/g, '/');
          if (/[+\-*/]{2,}/.test(sanitized)) return 'Error';
          return String(eval(sanitized));
        } catch {
          return 'Error';
        }
      }

      if (prev === '0' || prev === 'Error') return char;
      return prev + char;
    });
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const key = e.key;
      if (/[0-9+\-*/.=]/.test(key) || key === 'Enter' || key === 'Escape' || key === 'Backspace') {
        if (key === 'Backspace') {
          setExpression(prev => prev.length > 1 ? prev.slice(0, -1) : '0');
        } else {
          handleInput(key);
        }
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleInput]);

  return (
    <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
      <div className="bg-white p-6 rounded-2xl shadow-xl w-full max-w-sm">
        <Display value={expression} />
        <Keypad onPress={(val: string) => handleInput(val)} />
      </div>
    </div>
  );
}

