import React, { useState, useEffect } from 'react';
import { SearchBar } from './components/SearchBar';
import { CitySelector } from './components/CitySelector';
import { WeatherCard } from './components/WeatherCard';

interface WeatherData {
  city: string;
  current: { temp: number; condition: string };
  forecast: Array<{ day: string; temp: number; condition: string }>;
}

const MOCK_DATA: Record<string, WeatherData> = {
  'London': {
    city: 'London',
    current: { temp: 15, condition: 'Cloudy' },
    forecast: [
      { day: 'Mon', temp: 14, condition: 'Rainy' },
      { day: 'Tue', temp: 16, condition: 'Cloudy' },
      { day: 'Wed', temp: 18, condition: 'Sunny' },
      { day: 'Thu', temp: 17, condition: 'Cloudy' },
      { day: 'Fri', temp: 15, condition: 'Rainy' },
    ]
  },
  'New York': {
    city: 'New York',
    current: { temp: 22, condition: 'Sunny' },
    forecast: [
      { day: 'Mon', temp: 21, condition: 'Sunny' },
      { day: 'Tue', temp: 23, condition: 'Sunny' },
      { day: 'Wed', temp: 20, condition: 'Cloudy' },
      { day: 'Thu', temp: 19, condition: 'Rainy' },
      { day: 'Fri', temp: 21, condition: 'Sunny' },
    ]
  }
};

export default function App() {
  const [weather, setWeather] = useState<WeatherData | null>(null);

  const handleCityUpdate = (cityName: string) => {
    const data = MOCK_DATA[cityName] || MOCK_DATA['London'];
    setWeather(data);
  };

  useEffect(() => {
    handleCityUpdate('London');
  }, []);

  return (
    <div className="min-h-screen bg-gray-100 p-4 md:p-8">
      <div className="max-w-4xl mx-auto space-y-6">
        <header className="flex flex-col md:flex-row gap-4 justify-between items-center">
          <h1 className="text-2xl font-bold">Weather Dashboard</h1>
          <div className="flex gap-4">
            <SearchBar onSearch={(val) => handleCityUpdate(val)} />
            <CitySelector onSelect={(val) => handleCityUpdate(val)} />
          </div>
        </header>

        {weather && (
          <main className="space-y-8">
            <section className="bg-white p-6 rounded-lg shadow">
              <h2 className="text-xl font-semibold mb-4">{weather.city}</h2>
              <WeatherCard 
                day="Today" 
                temp={weather.current.temp} 
                condition={weather.current.condition} 
              />
            </section>

            <section>
              <h3 className="text-lg font-medium mb-4">5-Day Forecast</h3>
              <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-5 gap-4">
                {weather.forecast.map((day, idx) => (
                  <WeatherCard 
                    key={idx} 
                    day={day.day} 
                    temp={day.temp} 
                    condition={day.condition} 
                  />
                ))}
              </div>
            </section>
          </main>
        )}
      </div>
    </div>
  );
}
